  const db = await lesen();
  const p = objekt(db, "projekt", id);
  if (!p) throw nichtGefunden("Projekt nicht gefunden.");
  if (!istAdmin(n) && p.anbieterId !== n.id && !org.darfTeamLesenObjekt(db, n, p)) throw verboten();
