      provisionAkzeptiert: null,
      provisionSatz: null,
      ablehnGrund: "",
      aufrufe: 0,
      zustaendigId: null,
      veroeffentlichtAm: null,
      erstelltAm: jetzt(),
      geaendertAm: jetzt(),
    };
    p.slug = `${slugify(p.titel)}-${p.id.slice(-4).toLowerCase()}`;
    db.projekte.push(p);
    protokoll(db, n, "anlegen", "projekt", p.id, `Projekt „${p.titel}“ angelegt`, ip);
