    if (!bild?.daten) return this;
    const name = this.dok.bildName(bild);
    this.ops.push(`q ${zahl(b)} 0 0 ${zahl(h)} ${zahl(x)} ${this.y(y + h)} cm /${name} Do Q`);
    return this;
  }

  inhalt() {
    return this.ops.join("\n");
  }
}

