      aktion={daten.summe ? <Badge ton={daten.ueberfaellig ? "warn" : "info"}>{daten.summe} offen{daten.ueberfaellig ? ` · ${daten.ueberfaellig} überfällig` : ""}</Badge> : null}
    >
