def _aufgabe(art, t, link, frist="", ton="warn"):
	return {"art": art, "text": t, "link": link, "frist": frist, "ton": ton, "ueberfaellig": bool(frist) and frist < K.heute_wien()}


@frappe.whitelist(methods=["POST"])
def cockpit(als_benutzer=None):
