			auf += [_aufgabe("vorkenntnis", f"Vorkenntnis-Meldung zu {vk.get('pseudonym')} entscheiden", link) for vk in aus_json(z.vorkenntnis, []) or [] if vk.get("status") == "gemeldet"]
