  typ: "freiflaeche", land: "DE", bundesland: "Bayern", region: "Schwaben (Test)", mwp: 8, phase: "rtb", netzanschluss: "zusage", codGeplant: "2027-10", preisModus: "proKwp", preisProKwp: 95,
