const { readFileSync } = await import("node:fs");
const db = JSON.parse(readFileSync(".data/plattform.json", "utf8"));
const id = (e) => db.nutzer.find((u) => u.email === e).id;
const n = async (e) => D.nutzerFuerSitzung(id(e));
const adm = await n("admin@example.com"), anb = await n("anbieter@example.com"), inv = await n("investor@example.com");
const log = (t, x) => console.log(t, typeof x === "string" ? x : JSON.stringify(x)?.slice(0, 300));
const tryit = async (t, f) => { try { const r = await f(); log("OK  " + t, r?.status ?? ""); return r; } catch (e) { log("ERR " + t, `${e.status} ${e.message}`); return null; } };
const GR = { typ: "freiflaeche", land: "DE", bundesland: "Bayern", region: "Schwaben (Test)", mwp: 8, phase: "rtb", netzanschluss: "zusage", codGeplant: "2027-10", preisModus: "proKwp", preisProKwp: 95, beschreibung: "Testprojekt aus dem automatischen Anbieter-Test. Baureif, Netzzusage vorhanden. Keine echten Angaben, rein fiktiv.", vertraulich: { gemeinde: "Simgemeinde" } };
